{"i":712,"type":"thought","stage":"pit","round":5,"phase":"last_words","name":"Bex","text":"I was eliminated by my own anchor position. Gus climbed, leaving me to sink."}
{"i":714,"type":"last_words","stage":"pit","round":5,"phase":"last_words","name":"Bex","deathEvent":710,"text":"Gus survived the climb. I anchored and sank. A clean end. Judge them fairly."}
{"i":715,"type":"stage_end","stage":"pit","round":5,"phase":"play","survivors":["Ash","Fenn","Gus"]}
